 // FG356 hell entry (native CParty::dungeon_start + CheckHaveHellPartyPassItem +
 // CheckDestroyConditionSealDoor + UseSealDoorItems):
 //  * [hell dungeon] must be set for the world map that carries this dungeon;
 //  * a [hell freepass item] holder enters for free, otherwise every [item condition] item must be
 //    held x getHellPartyEntranceItemNeedCount(minLevel) and the dungeon must be minLevel>=45;
 //  * the consumed stack is charged through the run-scoped economy ledger (replay-safe);
 //  * the forced-hell difficulty roll keeps the native cumulative table (A=60/B=40 -> 1/2).
 // Failure returns 0 after sending the native {0,0x1b,count,items} op16 reject.
 byte[] HellEntryFailure(List<uint> missing){
  List<uint> rows=new List<uint>();foreach(uint id in missing)if(id<=0xFFFF)rows.Add(id);
  byte[] body=new byte[3+2*rows.Count];body[0]=0;body[1]=0x1b;body[2]=(byte)rows.Count;
  for(int i=0;i<rows.Count;i++)BitConverter.GetBytes((ushort)rows[i]).CopyTo(body,3+2*i);
  return Offline70RoleProtocol.BatchPacketFG(1,16,body,keys,false);
 }
 int HellEntryPrepare(ushort dungeonId,byte difficulty,string runId,out byte hellEventType){
  hellEventType=0;
  int minLevel=Offline70ForestFG75.MinimumLevel(dungeonId);
  Offline70HellEntryFG356.Decision decision=Offline70HellEntryFG356.Check(dungeonId,assets,minLevel);
  // Native CheckHaveHellPartyPassItem returns "pass" when the world map is not a hell map, so an
  // explicit type1 request there simply enters the ordinary dungeon (no hell room, no item use).
  if(decision.Code==2){Note("HELL_ENTRY_IGNORED dungeon="+dungeonId+" reason=notHellWorldMap");return -1;}
  if(!decision.Ok){Send("dungeon-entry-hell-failed",HellEntryFailure(decision.Missing));Note("HELL_ENTRY_REJECTED dungeon="+dungeonId+" code="+decision.Code+" need="+decision.Need+" missing="+decision.Missing.Count);return 0;}
