  Random rng=new Random(unchecked(Environment.TickCount*53+dungeonId*97+difficulty));
  byte hellDifficulty=Offline70HellFG356.RollForcedDifficulty(rng);
  if(hellDifficulty==0){Send("dungeon-entry-hell-failed",HellEntryFailure(new List<uint>()));Note("HELL_ENTRY_REJECTED dungeon="+dungeonId+" reason=difficultyRoll");return 0;}
  hellEventType=Offline70HellFG356.EventType(hellDifficulty);
  List<uint> consumeItems=new List<uint>();List<uint> consumeCounts=new List<uint>();
  if(decision.FreepassIndex>=0){consumeItems.Add(hell.FreepassItems[decision.FreepassIndex]);consumeCounts.Add(hell.FreepassCounts[decision.FreepassIndex]);}
  else foreach(uint id in hell.Conditions){consumeItems.Add(id);consumeCounts.Add((uint)decision.Need);}
  Offline70EconomyState before=assets;Dictionary<ushort,uint> collection=CollectionSnapshot();bool duplicate;
  try{
   assets=Offline70Economy.Apply(economyPath,runId+"-hell-pass","hell-pass",dungeonId+":"+hellDifficulty+":"+consumeItems.Count,delegate(Offline70EconomyState state){for(int i=0;i<consumeItems.Count;i++)Offline70Economy.RemoveAssetItem(state,consumeItems[i],consumeCounts[i]);},out duplicate);
  }catch(InvalidDataException e){Send("dungeon-entry-hell-failed",HellEntryFailure(consumeItems));Note("HELL_ENTRY_REJECTED dungeon="+dungeonId+" reason=consume "+e.Message);return 0;}
  if(!duplicate){Send("hell-pass-assets",Offline70EconomyProtocol.InventoryChangeReply(before,assets,keys));CollectionChanged(collection);}
  Note("HELL_ENTRY_ACCEPTED dungeon="+dungeonId+" difficulty="+hellDifficulty+" event="+hellEventType+" freepass="+(decision.FreepassIndex>=0?hell.FreepassItems[decision.FreepassIndex].ToString():"-" )+" need="+decision.Need+" duplicate="+duplicate);
